package com.lqq.supportflow.knowledge.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper; import com.lqq.supportflow.knowledge.domain.*; import java.time.Instant; import org.springframework.stereotype.Component;
@Component public class MyBatisKnowledgeDocumentAdapter implements KnowledgeDocumentPort { private final KnowledgeDocumentMapper mapper; public MyBatisKnowledgeDocumentAdapter(KnowledgeDocumentMapper mapper){this.mapper=mapper;}
 public boolean exists(Long t,Long b,String h){return mapper.exists(new QueryWrapper<KnowledgeDocumentEntity>().eq("tenant_id",t).eq("knowledge_base_id",b).eq("content_hash",h));}
 public KnowledgeDocument save(Long t,Long b,String f,String h){Instant now=Instant.now();KnowledgeDocumentEntity e=new KnowledgeDocumentEntity();e.tenantId=t;e.knowledgeBaseId=b;e.fileName=f;e.contentHash=h;e.status=IngestionStatus.UPLOADED.name();e.retryCount=0;e.createdAt=now;e.updatedAt=now;mapper.insert(e);return new KnowledgeDocument(e.id,f,h,IngestionStatus.UPLOADED);} public KnowledgeDocument transitionStatus(Long tenantId,Long documentId,IngestionStatus from,IngestionStatus to){if(!from.canTransitionTo(to))throw new IllegalArgumentException("invalid ingestion status transition");int updated=mapper.update(new KnowledgeDocumentEntity(),new UpdateWrapper<KnowledgeDocumentEntity>().eq("id",documentId).eq("tenant_id",tenantId).eq("status",from.name()).set("status",to.name()).set("updated_at",Instant.now()));if(updated!=1)throw new IllegalArgumentException("document status cannot be transitioned");KnowledgeDocumentEntity entity=mapper.selectById(documentId);return new KnowledgeDocument(entity.id,entity.fileName,entity.contentHash,to);} public java.util.Optional<KnowledgeDocument> findById(Long tenantId,Long knowledgeBaseId,Long documentId){KnowledgeDocumentEntity entity=mapper.selectOne(new QueryWrapper<KnowledgeDocumentEntity>().eq("id",documentId).eq("tenant_id",tenantId).eq("knowledge_base_id",knowledgeBaseId));return java.util.Optional.ofNullable(entity).map(value->new KnowledgeDocument(value.id,value.fileName,value.contentHash,IngestionStatus.valueOf(value.status)));}}
